import{_ as i}from"./chunks/qgc_mc_pid_tuning_rate_controller.CKJFCyuw.js";import{_ as s}from"./chunks/qgc_mc_pid_tuning_simple_control.C98VxfZ9.js";import{_ as l,o as a,c as n,al as r,j as e,a as t}from"./chunks/framework.7vp1BMOE.js";const b=JSON.parse('{"title":"멀티콥터 PID 튜닝 가이드","description":"","frontmatter":{},"headers":[],"relativePath":"ko/config_mc/pid_tuning_guide_multicopter_basic.md","filePath":"ko/config_mc/pid_tuning_guide_multicopter_basic.md"}'),c={name:"ko/config_mc/pid_tuning_guide_multicopter_basic.md"};function p(h,o,u,m,d,g){return a(),n("div",null,[...o[0]||(o[0]=[r('<h1 id="멀티콥터-pid-튜닝-가이드" tabindex="-1">멀티콥터 PID 튜닝 가이드 <a class="header-anchor" href="#멀티콥터-pid-튜닝-가이드" aria-label="Permalink to &quot;멀티콥터 PID 튜닝 가이드&quot;">​</a></h1><p>This tutorial explains how to <em>manually</em> tune the PID loops on PX4 for all <a href="./../airframes/airframe_reference#copter">multicopter setups</a> (Quads, Hexa, Octo etc).</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><a href="./../config/autotune_mc">Autotune</a> is recommended for most users, as it is far faster, easier and provides good tuning for most frames. 예를 들어, 새로운 ESC 또는 모터에는 다른 튜닝 게인이 필요합니다.</p></div><p>Generally if you&#39;re using an appropriate <a href="./../airframes/airframe_reference#copter">supported frame configuration</a>, the default tuning should allow you to fly the vehicle safely. Tuning is recommended for all new vehicle setups to get the <em>very best</em> performance, because relatively small hardware and assembly changes can affect the gains required tuning gains for optimal flight. For example, different ESCs or motors change the optimal tuning gains.</p><h2 id="소개" tabindex="-1">소개 <a class="header-anchor" href="#소개" aria-label="Permalink to &quot;소개&quot;">​</a></h2><p>PX4 uses <strong>P</strong>roportional, <strong>I</strong>integral, <strong>D</strong>erivative (PID) controllers (these are the most widespread control technique).</p><p>The <em>QGroundControl</em> <strong>PID Tuning</strong> setup provides real-time plots of the vehicle setpoint and response curves. The goal of tuning is to set the P/I/D values such that the <em>Response</em> curve matches the <em>Setpoint</em> curve as closely as possible (i.e. a fast response without overshoots).</p><p><img src="'+i+'" alt="QGC Rate Controller Tuning UI"></p><p>컨트롤러는 계층화되어 있어 상위 수준의 컨트롤러 결과를 하위 수준의 컨트롤러로 전달합니다. The lowest-level controller is the <strong>rate controller</strong>, followed by the <strong>attitude controller</strong>, and finally the <strong>velocity &amp; position controller</strong>. PID 튜닝은 다른 모든 컨트롤러에 영향을 미치므로 속도 컨트롤러부터 시작하여 동일한 순서로 수행해야합니다.</p>',9),e("p",null,[t("The testing procedure for each controller (rate, attitude, velocity/position) and axis (yaw, roll, pitch) is always the same: create a fast setpoint change by moving the sticks very rapidly and observe the response. 가장 낮은 수준의 컨트롤러는 "),e("strong",{"x-id":"1"},"속도 컨트롤러"),t(", "),e("strong",{"x-id":"1"},"태도 컨트롤러"),t(", 마지막으로 "),e("strong",{"x-id":"1"},"속도 & 위치 컨트롤러"),t(" 입니다.")],-1),r('<div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>속도 컨트롤러 조정이 가장 중요하며 잘 조정된 경우 다른 컨트롤러는 종종 약간의 조정만 필요하거나 필요하지 않습니다.</li><li>일반적으로 롤 및 피치에 동일한 튜닝 게인을 사용할 수 있습니다.</li><li>곡예/안정화/고도 모드를 사용하여 속도 컨트롤러 조정</li><li>Use <a href="./../flight_modes_mc/position">Position mode</a> to tune the <em>Velocity Controller</em> and the <em>Position Controller</em>. Make sure to switch to the <em>Simple position control</em> mode so you can generate step inputs. <img src="'+s+'" alt="QGC PID tuning: Simple control selector"></li></ul></div><h2 id="전제-조건" tabindex="-1">전제 조건 <a class="header-anchor" href="#전제-조건" aria-label="Permalink to &quot;전제 조건&quot;">​</a></h2><ul><li><p>You have selected the closest matching <a href="./../config/airframe">default frame configuration</a> for your vehicle. This should give you a vehicle that already flies.</p></li><li><p>You should have done an <a href="./../advanced_config/esc_calibration">ESC calibration</a>.</p></li><li><p>If using PWM outputs their minimum values should be set correctly in the <a href="./../config/actuators">Actuator Configuration</a>. These need to be set low, but such that the <strong>motors never stop</strong> when the vehicle is armed.</p><p>This can be tested in <a href="./../flight_modes_mc/acro">Acro mode</a> or in <a href="./../flight_modes_mc/manual_stabilized">Stabilized mode</a>:</p><ul><li>Remove propellers</li><li>Arm the vehicle and lower the throttle to the minimum</li><li>Tilt the vehicle to all directions, about 60 degrees</li><li>Check that no motors turn off</li></ul></li><li><p>Use a high-rate telemetry link such as WiFi if at all possible (a typical low-range telemetry radio is not fast enough for real-time feedback and plots). This is particularly important for the rate controller.</p></li><li><p>Disable <a href="./../advanced_config/parameter_reference#MC_AIRMODE">MC_AIRMODE</a> before tuning a vehicle (there is an options for this in the PID tuning screen).</p></li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Poorly tuned vehicles are likely to be unstable, and easy to crash. Make sure to have assigned a <a href="./../config/safety#emergency-switches">Kill switch</a>.</p></div><h2 id="tuning-procedure" tabindex="-1">Tuning Procedure <a class="header-anchor" href="#tuning-procedure" aria-label="Permalink to &quot;Tuning Procedure&quot;">​</a></h2><p>The tuning procedure is:</p><ol><li><p>Arm the vehicle, takeoff, and hover (typically in <a href="./../flight_modes_mc/position">Position mode</a>).</p></li><li><p>Open <em>QGroundControl</em> <strong>Vehicle Setup &gt; PID Tuning</strong><img src="'+i+`" alt="QGC Rate Controller Tuning UI"></p></li><li><p>Select the <strong>Rate Controller</strong> tab.</p></li><li><p>Confirm that the airmode selector is set to <strong>Disabled</strong></p></li><li><p>Set the <em>Thrust curve</em> value to: 0.3 (PWM, power-based controllers) or 1 (RPM-based ESCs)</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>For PWM, power-based and (some) UAVCAN speed controllers, the control signal to thrust relationship may not be linear. As a result, the optimal tuning at hover thrust may not be ideal when the vehicle is operating at higher thrust.</p><p>The thrust curve value can be used to compensate for this non-linearity:</p><ul><li>For PWM controllers, 0.3 is a good default (which may benefit from <a href="./../config_mc/pid_tuning_guide_multicopter#thrust-curve">further tuning</a>).</li><li>For RPM-based controllers, use 1 (no further tuning is required as these have a quadratic thrust curve).</li></ul><p>For more information see the <a href="./../config_mc/pid_tuning_guide_multicopter#thrust-curve">detailed PID tuning guide</a>.</p></div></li></ol><p>:::</p><ol start="6"><li><p>Set the <em>Select Tuning</em> radio button to: <strong>Roll</strong>.</p></li><li><p>(Optionally) Select the <strong>Automatic Flight Mode Switching</strong> checkbox. This will <em>automatically</em> switch from <a href="./../flight_modes_mc/position">Position mode</a> to <a href="./../flight_modes_mc/manual_stabilized">Stabilised mode</a> when you press the <strong>Start</strong> button</p></li><li><p>For rate controller tuning switch to <em>Acro mode</em>, <em>Stabilized mode</em> or <em>Altitude mode</em> (unless automatic switching is enabled).</p></li><li><p>Select the <strong>Start</strong> button in order to start tracking the setpoint and response curves.</p></li><li><p>Rapidly move the <em>roll stick</em> full range and observe the step response on the plots.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Stop tracking to enable easier inspection of the plots. This happens automatically when you zoom/pan. Use the <strong>Start</strong> button to restart the plots, and <strong>Clear</strong> to reset them.</p></div></li></ol><p>:::</p><ol start="11"><li><p>Modify the three PID values using the sliders (for roll rate-tuning these affect <code>MC_ROLLRATE_K</code>, <code>MC_ROLLRATE_I</code>, <code>MC_ROLLRATE_D</code>) and observe the step response again. The values are saved to the vehicle as soon as the sliders are moved.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The goal is for the <em>Response</em> curve to match the <em>Setpoint</em> curve as closely as possible (i.e. a fast response without overshoots).</p></div></li></ol><p>:::</p><pre><code>The PID values can be adjusted as follows:

- P (비례) 또는 K 이득 :
  - 더 많은 응답을 위해 이것을 늘리십시오.
  - 응답이 오버 슈팅 및/또는 진동하는 경우 감소합니다 (특정 지점까지 D 게인 증가도 도움이 됨).
- D (미분) 이득 :
  - 오버슈트 및 진동을 줄이기 위해이 값을 늘릴 수 있습니다.
  - 소음을 증폭하고 모터가 뜨거워 질 수 있으므로 필요한 만큼만 늘리십시오.
- I (적분) 이득 :
  - 정상 상태 오류를 줄이는 데 사용
  - 너무 낮으면 응답이 설정 값에 도달하지 못할 수 있습니다 (예 : 바람)
  - 너무 높으면 느린 진동이 발생할 수 있습니다.
</code></pre><ol start="12"><li>피치와 요에 대해 위의 튜닝 프로세스를 반복합니다. <ul><li>Use <em>Select Tuning</em> radio button to select the axis to tune</li><li>적절한 스틱을 이동합니다 (예 : 피치 스틱, 요 스틱).</li><li>피치 튜닝의 경우 롤과 동일한 값으로 시작하십시오.<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use the <strong>Save to Clipboard</strong> and <strong>Reset from Clipboard</strong> buttons to copy the roll settings for initial pitch settings.</p></div></li></ul></li></ol><p>:::</p><ol start="13"><li><p>모든 축에서 자세 콘트롤러에 대하여 튜닝 프로세스를 반복하십시오.</p></li><li><p>Repeat the tuning process for the velocity and positions controllers (on all the axes).</p><ul><li><p>Use Position mode when tuning these controllers</p></li><li><p>Select the <strong>Simple position control</strong> option in the <em>Position control mode ...</em> selector (this allows direct control for the generation of step inputs)</p><p><img src="`+s+'" alt="QGC PID tuning: Simple control selector"></p></li></ul></li></ol><p>완료되었습니다 ! 설정을 종료하기 전에 에어 모드를 다시 활성화하여야 합니다.</p>',17)])])}const y=l(c,[["render",p]]);export{b as __pageData,y as default};
